plugins {
    alias(libs.plugins.android.library)
    alias(libs.plugins.ksp)
}

// Never published. `kotrace-room` compiles and tests against its Room 2.6.1 floor (ADR-027); an app on Room 2.8 runs
// it under code generated by Room 2.8's own compiler, which calls other runtime APIs. So this module compiles the same
// real-database tests with Room 2.8, its compiler included, and `check` runs both.
android {
    namespace = "dev.kotrace.room.room28test"
    compileSdk {
        version = release(libs.versions.androidCompileSdk.get().toInt())
    }

    defaultConfig {
        // Room 2.8's own floor.
        minSdk = 23
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_11
        targetCompatibility = JavaVersion.VERSION_11
    }

    sourceSets.named("test") { kotlin.srcDir("../kotrace-room/src/testDatabase/kotlin") }
}

dependencies {
    testImplementation(project(":kotrace-room"))
    testImplementation(libs.room28.runtime)
    testImplementation(libs.room28.ktx)
    kspTest(libs.room28.compiler)
    testImplementation(libs.robolectric)
    testImplementation(libs.junit)
    testImplementation(libs.kotlinx.coroutines.test)
}
